INSERT OR IGNORE INTO portfolio_content (id, data_json, updated_at) VALUES (1, '{"identity":{"name":"hallworld","title":"Junior Security Developer","location":"Doha, Qatar","email":"hallworld@atomicmail.io"},"links":[{"label":"GitHub","url":"https://github.com/coqs"},{"label":"HackerOne","url":"https://hackerone.com/hallworld"},{"label":"Art","url":"https://www.deviantart.com/hallworld"}],"summary":"Junior security developer and pentester focused on web application security, responsible disclosure, and building useful software. Comfortable moving between reconnaissance, exploitation, clean backend code, and practical frontend work.","experience":[{"role":"Independent Security Researcher","organization":"Responsible disclosure and bug bounty programs","dates":"2025 — Present","bullets":["Reported high-impact authorization and data-exposure issues through private programs without publishing sensitive target details.","Active in web application testing, reconnaissance, vulnerability validation, and clear engagement-style reporting."]}],"education":[{"school":"Cybersecurity studies","details":"Network security, web application security, programming, cryptography, and intelligence fundamentals","dates":"Current"}],"skills":[{"label":"Security","value":"Web application security, OWASP Top 10, reconnaissance, responsible disclosure, basic Linux hardening"},{"label":"Development","value":"JavaScript, React, Node.js, Next.js, HTML/CSS, basic Python, basic C++"},{"label":"Tools","value":"Burp Suite, Wireshark, Kali Linux, GitHub, REST APIs, Cloudflare Workers"}],"activities":["Reverse engineering games","Bug bounty research","AI and robotics competitions"],"awards":["1st place — AI & Robotics 2026 Qatar competition, line-following challenge"],"certifications":[]}', '2026-08-09T00:00:00.000Z');

INSERT OR IGNORE INTO projects (slug, title, summary, details, tech_json, url, featured, sort_order, updated_at) VALUES
('yafc', 'YAFC — Yet Another File Cleaner', 'A modern Windows file-management and cleaning tool built around resumable sessions.', 'YAFC combines native folder picking, media/document/archive previews, keyboard-driven keep/delete decisions, completion statistics, and automatic session resume. The project uses a React frontend and Node/Express backend.', '["JavaScript","React","Vite","Node.js","Express"]', 'https://github.com/coqs/yafc', 1, 1, '2026-08-09T00:00:00.000Z'),
('tryon', 'TryOn', 'An AI virtual try-on experiment using Gemini Nano Banana through OpenRouter.', 'TryOn explores image input and output workflows, including Base64 image handling between a separate frontend and backend. It was built to learn how to connect an image-generation model to a practical user flow.', '["JavaScript","Gemini","OpenRouter","Node.js"]', 'https://github.com/coqs/tryon', 1, 2, '2026-08-09T00:00:00.000Z');
